command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "24dabf61314e81117fceccc74855f52d2deb75e0") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }

git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "fast-forward main failed" }
if ((git rev-parse HEAD).Trim() -ne "24dabf61314e81117fceccc74855f52d2deb75e0") { throw "persistent checkout main mismatch" }

python -X utf8 tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "remote-shell guidance contract failed" }

cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

$stale = git ls-remote --heads origin work/direct-shell-context-column-resize
if ($LASTEXITCODE -ne 0) { throw "branch existence check failed" }
if ($stale) {
  git push origin --delete work/direct-shell-context-column-resize
  if ($LASTEXITCODE -ne 0) { throw "accepted work branch cleanup failed" }
  Write-Host "WORK_BRANCH_CLEANUP=deleted"
} else {
  Write-Host "WORK_BRANCH_CLEANUP=already-absent"
}

git diff --check HEAD^..HEAD
if ($LASTEXITCODE -ne 0) { throw "guidance diff check failed" }
Write-Host "REMOTE_SHELL_GUIDANCE_CONTRACT_PASS"
